import java.awt.image.BufferedImage; import java.io.File; import javax.imageio.ImageIO; public class check_img { public static void main(String[] args) throws Exception { BufferedImage img = ImageIO.read(new File("assets/models/village/grass_texture.png")); for(int y=0; y<32; y++) { for(int x=0; x<32; x++) { int rgb = img.getRGB(x,y); int r = (rgb>>16)&0xFF; int g = (rgb>>8)&0xFF; int b = rgb&0xFF; if (r>80 && g<80 && b<80) System.out.print("#"); else if (r>40 && r>g) System.out.print("#"); else if (g>100) System.out.print("V"); else if (g>80) System.out.print("."); else System.out.print(" "); } System.out.println(); } } }
